window.DEX_DATA["sources:backport-06ae078a221d20ae"]={"json":{"skins":[{"filename":"galacticgruntmale.png"}],"names":[{"name":"银河队队员"}],"chat":[{"lines":[{"text":"帕路奇亚到底为什么有水属性啊？"},{"text":"操纵空间，哪一点像水属性？"}]},{"lines":[{"text":"帝牙卢卡和帕路奇亚够吓人了，可你见过骑拉帝纳吗？"},{"text":"那可是毁坏世界的统治者，简直像恶魔一样！"},{"text":"还有它的起源形态，根本是噩梦的素材！"}]},{"lines":[{"text":"我们要……等等，我们的目标是什么来着？"},{"text":"好像和宇宙有关……也许是冥王星？"},{"text":"对，就是这个！我们要让冥王星重新成为行星！"}]}]}};
